(7386510, 1148586, 46918, '<td valign="top">Hello from the critique club...<br/> <br/>Janine very nice image. Great editing. I like the water / dew droplets. Congrats on a top 10 finish. Happy shooting</td>', 'Hello from the critique club... Janine very nice image. Great editing. I like the water / dew droplets. Congrats on a top 10 finish. Happy shooting', '2015-07-13 17:44:31.000000', NULL, 0),
(7386519, 1148783, 46918, '<td valign="top">Hello from the critique club....<br/> <br/>This scored kind of middle of the road in this challenge. I think the reason for that might be subject matter. I am not talking about the church, the puddle, or the cobblestone street. It is a mix of all of the above. This shot to me is a little blah. Now the technical are good. Your focus is where it needs to be. The detail in the stones and water are good. Don''t let a middle of the road shot get you down. I want to see more of your pics. Happy shooting.</td>', 'Hello from the critique club.... This scored kind of middle of the road in this challenge. I think the reason for that might be subject matter. I am not talking about the church, the puddle, or the cobblestone street. It is a mix of all of the above. This shot to me is a little blah. Now the technical are good. Your focus is where it needs to be. The detail in the stones and water are good. Don''t let a middle of the road shot get you down. I want to see more of your pics. Happy shooting.', '2015-07-13 18:03:17.000000', NULL, 0),
(7445339, 1147911, 97225, '<td valign="top">Fabulous shot! Black and white is so much better even though the coloured version is good.</td>', 'Fabulous shot! Black and white is so much better even though the coloured version is good.', '2016-03-21 19:13:10.000000', NULL, 0);
